from typing import Any, Union
from weakref import WeakValueDictionary
from atexit import register


class TokenStorage:
    """Multiton class for storing and sharing access tokens per connection."""

    _instances: Any = WeakValueDictionary()

    def __new__(cls, connection_name):
        if connection_name not in cls._instances:
            instance = super().__new__(cls)
            cls._instances[connection_name] = instance

        return cls._instances[connection_name]

    def __init__(self, connection_name):
        if not hasattr(self, "_initialized"):
            self._initialized = True
            self.connection_name = connection_name

            self.access_token: Union[str, None] = None
            self.expires_at: Union[str, None] = None

    @classmethod
    def remove_instance(cls, connection_name):
        """Removes instance for given connection_name"""
        if connection_name in cls._instances:
            del cls._instances[connection_name]

    @classmethod
    def clear_instances(cls):
        """Removes all existing instances of TokenStorage"""
        cls._instances.clear()

    @classmethod
    def set_default_token(cls, connection_name):
        cls._instances[connection_name].access_token = "DEUifiRBkKG5E2XzMDjRfl76ZC9Ub0wnz4XsNiRVBChTYbJcE3F"
        cls._instances[connection_name].expires_at = "Mon Jun 13 07:28:29 UTC 2099"

register(TokenStorage.clear_instances)
